      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
      margin-bottom: 36px;
    }
    .takeaway-card {
      background: rgba(255,255,255,0.03);
      border-radius: 12px;
      padding: 16px;
      border-left: 3px solid;
      position: relative;
