    .takeaway-card:nth-child(1) { border-color: #38bdf8; }
    .takeaway-card:nth-child(2) { border-color: #e07a4f; }
    .takeaway-card:nth-child(3) { border-color: #4285f4; }
    .takeaway-card:nth-child(4) { border-color: #a855f7; }
