      font-size: 11px;
      font-weight: 700;
      letter-spacing: 1px;
      text-transform: uppercase;
      color: #475569;
      margin-bottom: 6px;
    }
    .takeaway-text {
      font-size: 12.5px;
      line-height: 1.55;
      color: #cbd5e1;
    }
    .takeaway-text strong { color: #e2e8f0; }

    /* ── Footer ── */
    .footer {
      text-align: center;
      font-size: 10.5px;
      color: #334155;
