  const medalMap = { 1: '🥇', 2: '🥈', 3: '🥉' };
  const familyLabel = { openai: 'OpenAI', anthropic: 'Anthropic', google: 'Google', deepseek: 'DeepSeek' };

  data.forEach(d => {
    const isTop3 = d.rank <= 3;
    const barWidth = ((d.pct / maxPct) * 100).toFixed(1);
    const row = document.createElement('div');
    row.className = `lb-row${isTop3 ? ' top3' : ''}`;
    row.innerHTML = `
      <div class="lb-rank">${medalMap[d.rank] || d.rank}</div>
      <div class="lb-name-wrap">
        <div class="lb-model-name">${d.name}</div>
        <span class="lb-family-badge badge-${d.family}">${familyLabel[d.family]}</span>
      </div>
      <div class="lb-bar-wrap">
        <div class="lb-bar-bg"></div>
        <div class="lb-bar-fill bar-${d.family}" style="width:${barWidth}%"></div>
      </div>
      <div class="lb-score score-${d.family}">${d.pct}%</div>
    `;
    container.appendChild(row);
  });
</script>
